INSERT INTO convenience_service (
    provider_id, name, category_code, summary, description, contact_name, contact_phone, address,
    cover_image_path, service_status, audit_status, max_capacity, current_booked, avg_score, score_count
)
VALUES (
    #{providerId}, #{name}, #{categoryCode}, #{summary}, #{description}, #{contactName}, #{contactPhone}, #{address},
    #{coverImagePath}, #{serviceStatus}, #{auditStatus}, #{maxCapacity}, #{currentBooked}, #{avgScore}, #{scoreCount}
)

mapper.update:
UPDATE convenience_service s
SET score_count = (SELECT COUNT(1) FROM service_review WHERE service_id = #{id}),
    avg_score = (
        SELECT IFNULL(ROUND(AVG(rating), 2), 0.00)
        FROM service_review
        WHERE service_id = #{id}
    ),
    updated_at = NOW()
WHERE s.id = #{id}

mapper.select:
SELECT id, provider_id, name, category_code, summary, description, contact_name, contact_phone, address, cover_image_path, service_status, audit_status, audit_reason, reviewed_by, reviewed_at, max_capacity, current_booked, avg_score, score_count, created_at, updated_at FROM convenience_service
provider_id = #{providerId}
AND audit_status = #{auditStatus}
ORDER BY id DESC

SELECT id, provider_id, name, category_code, summary, description, contact_name, contact_phone, address, cover_image_path, service_status, audit_status, audit_reason, reviewed_by, reviewed_at, max_capacity, current_booked, avg_score, score_count, created_at, updated_at FROM convenience_service
audit_status = 'APPROVED'
AND ( name LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%') )
AND category_code = #{categoryCode}
AND service_status = #{serviceStatus}
ORDER BY avg_score DESC, id DESC
